-- Align with DB history: V4 fixed vehicle_info column type\n-- If column already exists as TEXT, this is a no-op\n\nDO cat\nBEGIN\n    IF EXISTS (SELECT 1 FROM information_schema.columns\n               WHERE table_name='vehicle_smartcar_mapping' AND column_name='vehicle_info') THEN\n        -- If it was JSONB earlier, convert to TEXT only if needed\n        -- Safe approach: create temp column, copy, drop old, rename\n        BEGIN\n            ALTER TABLE vehicle_smartcar_mapping ADD COLUMN IF NOT EXISTS vehicle_info_tmp TEXT;\n            UPDATE vehicle_smartcar_mapping SET vehicle_info_tmp = vehicle_info::text;\n            ALTER TABLE vehicle_smartcar_mapping DROP COLUMN vehicle_info;\n            ALTER TABLE vehicle_smartcar_mapping RENAME COLUMN vehicle_info_tmp TO vehicle_info;\n        EXCEPTION WHEN others THEN\n            -- If cast/drop fails, column is already TEXT; ignore\n            NULL;\n        END;\n    END IF;\nENDcat;\n
